const __pageData = JSON.parse('{"title":"Conversation assembly","description":"","frontmatter":{"editSource":"docs/subsystems/conversation.md","outline":[2,3]},"headers":[],"relativePath":"en/reference/subsystems/conversation.md","filePath":"en/reference/subsystems/conversation.md"}');
